-- Common fields for every table (09 الحقول المشتركة), before any new table is added:
--   * ids are UUIDv7 (time-ordered), generated by the server or the device;
--   * store tables are keyed by (tenant_id, id), so composite foreign keys, RLS and any later
--     partitioning by store use one index instead of two;
--   * `version` and `updated_at` are maintained by a trigger (If-Match, sync, audit).
-- Row-level security and the tenant_isolation policies created in 0001 are now also declared in
-- schema.ts (pgPolicy), so drizzle snapshots match the database; they are not recreated here.

-- Postgres 16 has no built-in UUIDv7: 48-bit Unix time in ms + random bits, version 7, variant 10.
CREATE FUNCTION uuid_generate_v7() RETURNS uuid
LANGUAGE plpgsql VOLATILE
AS $$
BEGIN
  RETURN encode(
    set_bit(
      set_bit(
        overlay(uuid_send(gen_random_uuid())
          placing substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
          FROM 1 FOR 6),
        52, 1),
      53, 1),
    'hex')::uuid;
END $$;--> statement-breakpoint

-- Every UPDATE bumps the row version and the update time; callers cannot set them.
CREATE FUNCTION bump_row_version() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.version := OLD.version + 1;
  NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint

ALTER TABLE "plans" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "platform_users" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "tenants" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "subscriptions" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "tenant_settings" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "branches" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "registers" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "roles" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "user_roles" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "user_roles" ADD COLUMN "updated_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['plans', 'platform_users', 'tenants', 'subscriptions', 'tenant_settings',
                           'branches', 'registers', 'roles', 'users', 'user_roles']
  LOOP
    EXECUTE format('CREATE TRIGGER bump_row_version BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION bump_row_version()', t);
  END LOOP;
END $$;--> statement-breakpoint

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['plans', 'platform_users', 'tenants', 'subscriptions', 'branches', 'registers',
                           'roles', 'users', 'user_roles', 'audit_logs', 'sessions']
  LOOP
    EXECUTE format('ALTER TABLE %I ALTER COLUMN id SET DEFAULT uuid_generate_v7()', t);
  END LOOP;
END $$;--> statement-breakpoint

-- Store tables: primary key (tenant_id, id). The composite foreign keys pointed at the separate
-- unique (tenant_id, id) constraints; they are re-created against the new primary keys.
ALTER TABLE "registers" DROP CONSTRAINT "registers_tenant_id_branch_id_branches_tenant_id_id_fk";--> statement-breakpoint
ALTER TABLE "user_roles" DROP CONSTRAINT "user_roles_tenant_id_user_id_users_tenant_id_id_fk";--> statement-breakpoint
ALTER TABLE "user_roles" DROP CONSTRAINT "user_roles_tenant_id_role_id_roles_tenant_id_id_fk";--> statement-breakpoint
ALTER TABLE "user_roles" DROP CONSTRAINT "user_roles_tenant_id_branch_id_branches_tenant_id_id_fk";--> statement-breakpoint
ALTER TABLE "sessions" DROP CONSTRAINT "sessions_tenant_id_user_id_users_tenant_id_id_fk";--> statement-breakpoint

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['subscriptions', 'branches', 'registers', 'roles', 'users', 'user_roles',
                           'audit_logs', 'sessions']
  LOOP
    EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I, ADD CONSTRAINT %I PRIMARY KEY (tenant_id, id)',
                   t, t || '_pkey', t || '_pkey');
  END LOOP;
END $$;--> statement-breakpoint

ALTER TABLE "branches" DROP CONSTRAINT "branches_tenant_id_unique";--> statement-breakpoint
